mapper.select:
select
    *
from vault_generation
where vault_id = #{vaultId}
and generation = #{generation}

select exists (
    select 1 from vault_item
    where vault_id = #{vaultId}
    and generation = #{generation}
    and item_id = #{itemId}
)

select
    *
from vault_idempotency_record
where account_id = #{accountId}
and operation = #{operation}
and idempotency_key = #{key}

mapper.delete:
delete from vault_item
where vault_id = #{vaultId}
and generation = #{generation}
and exists (
    select
        1
    from vault_generation g
    join vault_info v on v.id = g.vault_id
    where g.vault_id = #{vaultId}
    and g.generation = #{generation}
    and g.status in ('RETIRED', 'ABORTED')
    and (v.active_generation is null or v.active_generation <> g.generation)
)

delete fROM vault_key_slot
where vault_id = #{vaultId}
and generation = #{generation}
and exists (
    select
        1
    from vault_generation g
    join vault_info v on v.id = g.vault_id
    where g.vault_id = #{vaultId}
    and g.generation = #{generation}
    and g.status IN ('RETIRED', 'ABORTED')
    and (v.active_generation is null or v.active_generation <> g.generation)
)
